import { describe, it, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { CacheManager } from './cache-manager.js';
import type { Model } from './types.js';

function makeModel(id: string): Model {
  return {
    id,
    name: id,
    description: '',
    contextLength: 4096,
    pricing: { prompt: '0', completion: '0' },
    supportedParameters: [],
    defaultParameters: {},
    architecture: {},
    topProvider: {},
    outputModalities: ['text'],
    canonicalSlug: id,
    createdAt: null,
    expirationDate: null,
    perRequestLimits: null,
  };
}

describe('CacheManager', () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = mkdtempSync(join(tmpdir(), 'or-cache-test-'));
  });

  afterEach(() => {
    rmSync(tmpDir, { recursive: true, force: true });
  });

  it('returns null when no cache exists', () => {
    const cache = new CacheManager(tmpDir);
    assert.equal(cache.load(), null);
  });

  it('round-trips save/load', () => {
    const cache = new CacheManager(tmpDir);
    const models = [makeModel('test/model:free')];
    cache.save(models);

    const loaded = cache.load();
    assert.ok(loaded);
    assert.equal(loaded.length, 1);
    assert.equal(loaded[0].id, 'test/model:free');
  });

  it('returns null after TTL expires', () => {
    const cache = new CacheManager(tmpDir, 1); // 1ms TTL
    cache.save([makeModel('test:free')]);

    // Wait for TTL to expire
    const start = Date.now();
    while (Date.now() - start < 5) {} // busy-wait 5ms

    assert.equal(cache.load(), null);
  });

  it('returns null after invalidate', () => {
    const cache = new CacheManager(tmpDir);
    cache.save([makeModel('test:free')]);
    cache.invalidate();
    assert.equal(cache.load(), null);
  });

  it('getPath returns expected path', () => {
    const cache = new CacheManager(tmpDir);
    assert.ok(cache.getPath().includes('openrouter-model-cache.json'));
  });
});

