/**
 * Model Registry — fetches and caches all OpenRouter models dynamically.
 *
 * NEVER hardcodes model lists. Always queries OpenRouter API first,
 * falls back to local cache if the API is unreachable.
 */

import type { Model, ApiModel } from './types.js';
import { CacheManager } from './cache-manager.js';
import { ConfigLoader } from './config-loader.js';

const OR_BASE = 'https://openrouter.ai/api/v1';

export class ModelRegistry {
  private cache: CacheManager;
  private config: ConfigLoader;

  constructor(cache: CacheManager, config: ConfigLoader) {
    this.cache = cache;
    this.config = config;
  }

  /** Fetch all models from the OpenRouter API, falling back to cache. */
  async fetchAll(): Promise<Model[]> {
    const apiKey = this.config.getApiKey();
    if (!apiKey) {
      console.warn('⚠️  OPENROUTER_API_KEY not set. Using cached models only.');
      return this.cache.load() ?? [];
    }

    try {
      const resp = await fetch(`${OR_BASE}/models`, {
        headers: { Authorization: `Bearer ${apiKey}` },
        signal: AbortSignal.timeout(10_000),
      });

      if (!resp.ok) {
        throw new Error(`API error ${resp.status}: ${resp.statusText}`);
      }

      const json: { data: ApiModel[] } = (await resp.json()) as { data: ApiModel[] };
      const models = json.data.map(this.normalize);
      this.cache.save(models);
      return models;
    } catch (err) {
      console.warn(`⚠️  OpenRouter API fetch failed: ${err}`);
      const cached = this.cache.load();
      if (cached) return cached;
      throw new Error('Cannot reach OpenRouter API and no cache available.');
    }
  }

  /** Filter models tagged `:free`. */
  filterFree(models: Model[]): Model[] {
    return models.filter((m) => m.id.endsWith(':free'));
  }

  /** Filter by supported parameter (e.g. "tools", "vision"). */
  filterByParameter(models: Model[], param: string): Model[] {
    return models.filter((m) => m.supportedParameters.includes(param));
  }

  /** Filter by output modality. */
  filterByModality(models: Model[], modality: string): Model[] {
    return models.filter((m) =>
      modality === 'all' || (m.outputModalities ?? ['text']).includes(modality),
    );
  }

  /** Search by keyword in name or description. */
  search(models: Model[], term: string): Model[] {
    const lower = term.toLowerCase();
    return models.filter(
      (m) => m.name.toLowerCase().includes(lower) || m.description.toLowerCase().includes(lower),
    );
  }

  /** Normalize an API model into our internal Model type. */
  private normalize(api: ApiModel): Model {
    return {
      id: api.id,
      name: api.name ?? api.id,
      description: api.description ?? '',
      contextLength: api.context_length ?? 0,
      pricing: api.pricing ?? { prompt: '0', completion: '0' },
      supportedParameters: api.supported_parameters ?? [],
      defaultParameters: api.default_parameters ?? {},
      architecture: api.architecture ?? {},
      topProvider: api.top_provider ?? {},
      outputModalities: api.output_modalities ?? ['text'],
      canonicalSlug: api.canonical_slug ?? api.id,
      createdAt: api.created ? new Date(api.created * 1000) : null,
      expirationDate: api.expiration_date ?? null,
      perRequestLimits: api.per_request_limits ?? null,
    };
  }
}

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { CapabilityDetector } from './capability-detector.js';

describe('CapabilityDetector', () => {
  describe('detect', () => {
    it('detects vision from supported params', () => {
      const caps = CapabilityDetector.detect(['vision', 'tools']);
      assert.ok(caps.vision);
      assert.ok(caps.toolCalling);
    });

    it('detects image-input as vision', () => {
      const caps = CapabilityDetector.detect(['image-input']);
      assert.ok(caps.vision);
    });

    it('detects structured outputs', () => {
      const caps = CapabilityDetector.detect(['structured_outputs']);
      assert.ok(caps.structuredOutputs);
    });

    it('detects json_mode as structured outputs', () => {
      const caps = CapabilityDetector.detect(['json_mode']);
      assert.ok(caps.structuredOutputs);
    });

    it('detects reasoning', () => {
      const caps = CapabilityDetector.detect(['reasoning']);
      assert.ok(caps.reasoning);
    });

    it('detects include_reasoning as reasoning', () => {
      const caps = CapabilityDetector.detect(['include_reasoning']);
      assert.ok(caps.reasoning);
    });

    it('streaming true when stream param present', () => {
      const caps = CapabilityDetector.detect(['stream']);
      assert.ok(caps.streaming);
    });

    it('streaming true when no params (unknown model)', () => {
      const caps = CapabilityDetector.detect([]);
      assert.ok(caps.streaming);
    });

    it('streaming false when params exist but no stream', () => {
      const caps = CapabilityDetector.detect(['tools', 'vision']);
      assert.ok(!caps.streaming);
    });

    it('codeGeneration always true', () => {
      const caps = CapabilityDetector.detect([]);
      assert.ok(caps.codeGeneration);
    });

    it('is case-insensitive', () => {
      const caps = CapabilityDetector.detect(['Vision', 'TOOLS']);
      assert.ok(caps.vision);
      assert.ok(caps.toolCalling);
    });

    it('returns all false for unrecognized params (except streaming/code)', () => {
      const caps = CapabilityDetector.detect(['unknown_param']);
      assert.ok(!caps.vision);
      assert.ok(!caps.toolCalling);
      assert.ok(!caps.structuredOutputs);
      assert.ok(!caps.reasoning);
      assert.ok(!caps.functionCalling);
      assert.ok(!caps.streaming);
      assert.ok(caps.codeGeneration);
    });
  });

  describe('summary', () => {
    it('lists capabilities as emoji tags', () => {
      const caps = CapabilityDetector.detect(['vision', 'tools', 'reasoning']);
      const s = CapabilityDetector.summary(caps);
      assert.ok(s.includes('vision'));
      assert.ok(s.includes('tool-calling'));
      assert.ok(s.includes('reasoning'));
    });

    it('returns text-only for no caps', () => {
      const caps = CapabilityDetector.detect([]);
      const s = CapabilityDetector.summary(caps);
      assert.equal(s, '📝 text-only');
    });
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { AliasManager } from './alias-manager.js';

const MODELS = [
  { id: 'deepseek/deepseek-r1-0528:free' },
  { id: 'qwen/qwen3-32b:free' },
  { id: 'google/gemma-3-27b-it:free' },
  { id: 'meta-llama/llama-3.1-8b-instruct:free' },
  { id: 'mistralai/mistral-small-3.1-24b-instruct:free' },
  { id: 'microsoft/phi-4-mini-instruct:free' },
  { id: 'openai/gpt-4o:free' },
];

describe('AliasManager', () => {
  it('resolves built-in aliases', () => {
    const mgr = new AliasManager();
    assert.equal(mgr.resolve('r1'), 'deepseek/deepseek-r1-0528:free');
    assert.equal(mgr.resolve('qwen'), 'qwen/qwen3-32b:free');
    assert.equal(mgr.resolve('unknown'), null);
  });

  it('resolve is case-insensitive', () => {
    const mgr = new AliasManager();
    assert.equal(mgr.resolve('R1'), 'deepseek/deepseek-r1-0528:free');
  });

  it('isAlias works', () => {
    const mgr = new AliasManager();
    assert.ok(mgr.isAlias('r1'));
    assert.ok(!mgr.isAlias('nonexistent'));
  });

  it('add creates new alias', () => {
    const mgr = new AliasManager();
    mgr.add('custom', 'custom/model:free');
    assert.equal(mgr.resolve('custom'), 'custom/model:free');
  });

  it('list returns copy', () => {
    const mgr = new AliasManager();
    const list = mgr.list();
    list.delete('r1');
    // Original not affected
    assert.ok(mgr.isAlias('r1'));
  });

  describe('expandSelector', () => {
    it('returns openrouter/free for best-free', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('best-free', MODELS), 'openrouter/free');
    });

    it('returns :free suffixed selectors as-is', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('custom/model:free', MODELS), 'custom/model:free');
    });

    it('finds exact model ID match', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('openai/gpt-4o:free', MODELS), 'openai/gpt-4o:free');
    });

    it('resolves alias', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('r1', MODELS), 'deepseek/deepseek-r1-0528:free');
    });

    it('fuzzy match on unique substring', () => {
      const mgr = new AliasManager();
      // "gpt-4o" only appears in one model
      assert.equal(mgr.expandSelector('gpt-4o', MODELS), 'openai/gpt-4o:free');
    });

    it('returns null for ambiguous prefix', () => {
      const mgr = new AliasManager();
      // Multiple models contain common substrings
      assert.equal(mgr.expandSelector('free', MODELS), 'openrouter/free'); // alias takes precedence
    });

    it('returns null for no match', () => {
      const mgr = new AliasManager();
      assert.equal(mgr.expandSelector('nonexistent-xyz', MODELS), null);
    });
  });

  describe('validateAgainst', () => {
    it('removes stale aliases', () => {
      const mgr = new AliasManager();
      const stale = mgr.validateAgainst(MODELS);
      // r1 target exists in MODELS, qwen target exists, etc.
      // But some built-in targets might not be in our test MODELS
      assert.ok(Array.isArray(stale));
    });

    it('keeps aliases whose targets exist', () => {
      const mgr = new AliasManager();
      mgr.validateAgainst(MODELS);
      assert.ok(mgr.isAlias('r1')); // target is in MODELS
      assert.ok(mgr.isAlias('free')); // openrouter/free always valid
    });

    it('removes aliases whose targets are gone', () => {
      const mgr = new AliasManager();
      mgr.add('gone', 'removed/model:free');
      const stale = mgr.validateAgainst(MODELS);
      assert.ok(stale.includes('gone'));
      assert.ok(!mgr.isAlias('gone'));
    });
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { HealthChecker } from './health-checker.js';
import { ConfigLoader } from './config-loader.js';

describe('HealthChecker', () => {
  it('returns unavailable when no API key', async () => {
    const origKey = process.env.OPENROUTER_API_KEY;
    delete process.env.OPENROUTER_API_KEY;

    const config = new ConfigLoader();
    const checker = new HealthChecker(config);
    const result = await checker.ping('test/model:free');

    assert.equal(result.status, 'unavailable');
    assert.equal(result.error, 'No API key');
    assert.equal(result.modelId, 'test/model:free');

    if (origKey) process.env.OPENROUTER_API_KEY = origKey;
  });

  describe('checkMany', () => {
    it('returns results for all models (no key = all unavailable)', async () => {
      const origKey = process.env.OPENROUTER_API_KEY;
      delete process.env.OPENROUTER_API_KEY;

      const config = new ConfigLoader();
      const checker = new HealthChecker(config);
      const models = [
        { id: 'a:free', name: 'A', description: '', contextLength: 4096, pricing: { prompt: '0', completion: '0' }, supportedParameters: [], defaultParameters: {}, architecture: {}, topProvider: {}, outputModalities: ['text'], canonicalSlug: 'a:free', createdAt: null, expirationDate: null, perRequestLimits: null },
        { id: 'b:free', name: 'B', description: '', contextLength: 4096, pricing: { prompt: '0', completion: '0' }, supportedParameters: [], defaultParameters: {}, architecture: {}, topProvider: {}, outputModalities: ['text'], canonicalSlug: 'b:free', createdAt: null, expirationDate: null, perRequestLimits: null },
      ];

      const results = await checker.checkMany(models);
      assert.equal(results.length, 2);
      assert.equal(results[0].modelId, 'a:free');
      assert.equal(results[1].modelId, 'b:free');
      assert.ok(results.every((r) => r.status === 'unavailable'));

      if (origKey) process.env.OPENROUTER_API_KEY = origKey;
    });
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { FallbackRouter } from './fallback-router.js';
import { ProviderAdapter } from './provider-adapter.js';
import { HealthChecker } from './health-checker.js';
import { ConfigLoader } from './config-loader.js';
import type { Model } from './types.js';

function makeModel(id: string, ctx: number, params: string[] = []): Model {
  return {
    id,
    name: id,
    description: '',
    contextLength: ctx,
    pricing: { prompt: '0', completion: '0' },
    supportedParameters: params,
    defaultParameters: {},
    architecture: {},
    topProvider: {},
    outputModalities: ['text'],
    canonicalSlug: id,
    createdAt: null,
    expirationDate: null,
    perRequestLimits: null,
  };
}

describe('FallbackRouter', () => {
  const config = new ConfigLoader();
  const provider = new ProviderAdapter(config);
  const health = new HealthChecker(config);
  const router = new FallbackRouter(provider, health, config);

  const models: Model[] = [
    makeModel('a/small:free', 4096),
    makeModel('b/big:free', 128000, ['tools', 'vision']),
    makeModel('c/medium:free', 32000, ['tools']),
    makeModel('d/paid', 200000, ['tools', 'vision']),
  ];

  describe('selectBest', () => {
    it('returns highest context free model', () => {
      const best = router.selectBest(models);
      assert.ok(best);
      assert.equal(best.id, 'b/big:free');
    });

    it('filters by requirements', () => {
      const best = router.selectBest(models, { vision: true });
      assert.ok(best);
      assert.equal(best.id, 'b/big:free');
    });

    it('returns null if no free model matches requirements', () => {
      const best = router.selectBest(models, { reasoning: true });
      assert.equal(best, null);
    });

    it('ignores paid models', () => {
      const best = router.selectBest(models);
      assert.ok(best);
      assert.notEqual(best.id, 'd/paid');
    });

    it('returns null for empty list', () => {
      assert.equal(router.selectBest([]), null);
    });
  });

  describe('selectFastest', () => {
    it('picks lowest latency healthy model', () => {
      const results = [
        { modelId: 'a', status: 'healthy', latencyMs: 500 },
        { modelId: 'b', status: 'healthy', latencyMs: 100 },
        { modelId: 'c', status: 'degraded', latencyMs: 50 },
      ];
      assert.equal(router.selectFastest(results), 'b');
    });

    it('returns null when all unhealthy', () => {
      const results = [
        { modelId: 'a', status: 'unavailable', latencyMs: null },
        { modelId: 'b', status: 'degraded', latencyMs: 200 },
      ];
      assert.equal(router.selectFastest(results), null);
    });

    it('returns null for empty results', () => {
      assert.equal(router.selectFastest([]), null);
    });
  });
});

/**
 * Cache Manager — persists model metadata to disk.
 *
 * Cache file: ~/.opencode/openrouter-model-cache.json
 * TTL: 1 hour (configurable via `CACHE_TTL_MS` env var).
 */

import type { Model } from './types.js';
import { dirname, join } from 'path';
import { writeFileSync, readFileSync, existsSync, mkdirSync } from 'fs';

interface CacheEntry<T> {
  data: T;
  expiresAt: number;
}

function osHomedir(): string {
  return process.env.USERPROFILE || process.env.HOME || '/tmp';
}

const DEFAULT_CACHE_DIR = join(osHomedir(), '.opencode');
const DEFAULT_TTL_MS = 60 * 60 * 1000; // 1 hour

export class CacheManager {
  private cachePath: string;
  private ttl: number;

  constructor(cacheDir?: string, ttlMs?: number) {
    this.cachePath = join(cacheDir ?? DEFAULT_CACHE_DIR, 'openrouter-model-cache.json');
    const envTtl = parseInt(process.env.CACHE_TTL_MS ?? '', 10);
    this.ttl = ttlMs ?? (isNaN(envTtl) ? DEFAULT_TTL_MS : envTtl);
  }

  /** Load cached models, or null if missing/expired. */
  load(): Model[] | null {
    try {
      if (!existsSync(this.cachePath)) return null;
      const raw = readFileSync(this.cachePath, 'utf-8');
      const entry: CacheEntry<Model[]> = JSON.parse(raw);
      if (Date.now() > entry.expiresAt) {
        this.invalidate();
        return null;
      }
      return entry.data;
    } catch {
      return null;
    }
  }

  /** Save models to cache with TTL. */
  save(models: Model[]): void {
    try {
      mkdirSync(dirname(this.cachePath), { recursive: true });
      const entry: CacheEntry<Model[]> = {
        data: models,
        expiresAt: Date.now() + this.ttl,
      };
      writeFileSync(this.cachePath, JSON.stringify(entry, null, 2), {
        mode: 0o600,
      });
    } catch (err) {
      console.warn(`⚠️  Failed to write cache: ${err}`);
    }
  }

  /** Delete cached data. */
  invalidate(): void {
    try {
      if (existsSync(this.cachePath)) {
        writeFileSync(this.cachePath, '');
      }
    } catch {}
  }

  /** Return the cache file path for informational display. */
  getPath(): string {
    return this.cachePath;
  }
}

# Programmatic API Usage

This skill provides a programmatic API for integrating free models into other tools.

## TypeScript Interface

```typescript
import { OpenRouterFree } from './index.js';

const orf = new OpenRouterFree();
await orf.init();

// List free coding models
const codingModels = orf.listFree({ hasTools: true });

// Get best model by context length
const best = orf.router.selectBest(orf.models);

// Send a message with automatic fallback
const { result, decision } = await orf.router.sendWithFallback(
  orf.listFree(),
  [{ role: 'user', content: 'Hello!' }],
);

// Health check all models
const health = await orf.checkHealth();
```

## Environment Variables

| Variable | Default | Description |
|----------|---------|-------------|
| `OPENROUTER_API_KEY` | — | API key for OpenRouter (required) |
| `OPENROUTER_BASE_URL` | `https://openrouter.ai/api/v1` | Custom API endpoint |
| `CACHE_TTL_MS` | `3600000` | Cache TTL in milliseconds |
| `OPENROUTER_MAX_DISPLAY` | `30` | Max models to display in CLI |

