/**
 * OpenRouter Free Model Integration for OpenCode
 *
 * Dynamically discovers, caches, and connects to free AI models
 * via the OpenRouter API — zero hardcoded model lists.
 */

import { OpenRouterFree } from './src/index.js';

export { OpenRouterFree };
export type { Model, ChatMessage, ProviderResult, HealthResult, Capabilities } from './src/types.js';

/**
 * Config Loader — reads environment variables and optional config files.
 */

export class ConfigLoader {
  /** Get the OpenRouter API key from environment. */
  getApiKey(): string | null {
    return process.env.OPENROUTER_API_KEY ?? null;
  }

  /** Check if an API key is configured. */
  hasApiKey(): boolean {
    return !!this.getApiKey();
  }

  /** Get the base URL (overridable for proxies/self-hosted routers). */
  getBaseUrl(): string {
    return process.env.OPENROUTER_BASE_URL || 'https://openrouter.ai/api/v1';
  }

  /** Get cache TTL override. */
  getCacheTtl(): number | null {
    const val = parseInt(process.env.CACHE_TTL_MS ?? '', 10);
    return isNaN(val) ? null : val;
  }

  /** Get the maximum number of models to display. */
  getMaxDisplay(): number {
    return parseInt(process.env.OPENROUTER_MAX_DISPLAY ?? '30', 10);
  }
}

